for (const unit of UNITS) {
  unit.vocabIds = [...new Set(unit.lessons.flatMap((lesson) => lesson.vocab))];
  unit.checkpoint = {
    id: `${unit.id}-checkpoint`,
    title: `${unit.title} · Checkpoint`,
    subtitle: `${unit.vocabIds.length} kelimeyi tekrar et`,
    type: 'Checkpoint',
    vocab: unit.vocabIds,
    isCheckpoint: true,
    minutes: 8,
    grammar: unit.lessons[0].grammar,
  };
  unit.path = [...unit.lessons, unit.checkpoint];
}

export const ALL_LESSONS = Object.fromEntries(UNITS.flatMap((unit) => unit.path.map((lesson) => [lesson.id, { ...lesson, unitId: unit.id, unitNumber: unit.number, level: unit.level, unitTitle: unit.title, color: unit.color }])));

